def main():
    current=prepare.helper.read(ROOT/'project.json')
    assert current['asset_review']['status']=='approved'
    proposal=json.loads(json.dumps(current))
    proposal['aspect_ratio']='21:9'
    proposal['resolution']='720p'
    proposal['requested_native_dimensions']={'width':1470,'height':630,'source':'Current official Seedance 2.5 output table'}
    proposal['production_stage']='scene_prompts_ready'
    proposal['rendering'].update(route='user-authorized direct Seedance 2.5',authorization='please proceed. for the video specs, they should be 720p, 21:9',audio=True,watermark=False,storyboard_inputs=False)
    proposal['prompt_library_consulted']=['prompt-library/README.md','prompt-library/TEMPLATE.md','prompt-library/TAGS.md','prompt-library/INDEX.md','prompt-library/sections/04_active-references.md','prompt-library/shots/scene-10/06_close-detail-of-gloved-hands-and-a-child-s-teddy-b.md','prompt-library/shots/scene-11/17_an-interior-in-cold-daylight-a-woman-holding-an-in.md']
    for chapter,scene in zip(proposal['chapters'],SCENES):
        shots=[{'start':a,'end':b,'action':action,'camera':cam,'audio':audio,'end_state':end} for a,b,action,cam,audio,end in scene['shots']]
        all_text=scene['first']+' '+str(shots)
        used=prepare.helper.tags(all_text)
        tags=[a['tag'] for a in proposal['asset_list'] if a['tag'].casefold() in used]
        if '@Meadow' not in tags: tags.append('@Meadow')
        chapter['tagged_assets']=tags
        chapter['linked_asset_ids']=[]
        chapter['shots']=shots
        chapter['handoff']={'start':scene['first'],'end':shots[-1]['end_state']}
        prompt='SCENE CONTEXT\n'+chapter['scene_summary']+' The point is a gentle act of shared care, readable through physical action and expressive posture.\n\n'
        prompt+=f'OUTPUT SETTINGS\nExactly {chapter["duration"]} seconds, 21:9, 720p native output. Premium stylized 3D PLUSH ANIMATION, tactile microfiber characters, handcrafted miniature felt environment, rounded original cartoon proportions. Fluid small real-time movement, gentle expressive squash-and-stretch. No live-action people. Wordless. No titles, subtitles, captions, text, logos, watermarks or credits.\n\n'
        prompt+='ACTIVE REFERENCES\n'+'\n'.join(tag+': '+ROLE[tag] for tag in tags)+'\nCharacter sheets control identity, facial embroidery and assembled anatomy ONLY. Never render their studio backgrounds, panel arrangement, detached body/head views or additional copies. No keychains, rings, hanging loops, fabric product labels or writing. The two original photographs already grounded these selected sheets and are not scene compositions.\n\n'
        prompt+='LOCATION MAP / FIRST FRAME AND SPATIAL BLOCKING\n'+scene['first']+' Camera is a third-person plush-eye-level view; left sunset key and right slope maintain the established geography.\n\n'
        prompt+='FORMAT MODE / ACTION TIMING\nThree consecutive timed shots with the explicitly described hard cuts. No extra montage, flashback, added scene or unplanned transition.\n'
        for i,s in enumerate(shots,1):
            prompt+=f'Shot {i} ({s["start"]}-{s["end"]}s): CAMERA / OPTICS: {s["camera"]} VISUALS & ACTION: {s["action"]} AUDIO: {s["audio"]} END STATE: {s["end_state"]}\n'
        prompt+='\nPHYSICS\nSoft stuffed bodies have contact, weight and slightly compressible plush surfaces. Short feet plant on grass; only the blue teardrop naturally hovers low. Supporting paws touch the star before a transfer releases it. The star obeys the exact gentle fairytale floating described above, never teleporting. No snapping, limb growth, anatomical fusing, bouncing camera or uncontrolled throws. All short limbs remain plush paws/flippers, no human fingers. Preserve one star and its five points.\n\n'
        prompt+='LIGHTING\n'+scene['light']+' Soft tactile fiber highlights, pastel saturation, gentle contrast; preserve white, yellow, orange and blue character colors. Star bloom remains controlled so face embroidery is legible. No flashes, flare, strobe or neon.\n\n'
        prompt+='AUDIO\nNative synchronized sound. The complete layers are: soft evening breeze and tiny grass/felt Foley; only the timed chimes and nonverbal reactions listed; gentle celesta and soft pizzicato in a quiet C-major bedtime theme; closed-mouth wordless C5–E5–G5 humming ONLY where specified. Instrumental score stays low enough to hear the story clue. No human-language words, narration, spoken dialogue or sung lyrics in any language. If any vocal utterance beyond nonverbal humming occurs, Japanese is the only allowed spoken language; prefer none. No harsh sounds or dramatic action score.\n\n'
        character_count=sum(1 for tag in tags if tag in ('@Mochi','@Hina','@Tora','@Sora','@Mimi'))
        prompt+=f'POSITIVE CONSTRAINTS / CONTINUITY LOCKS\nExactly {character_count} named friends exist in this scene, each ONCE, plus ONE baby-star prop. Only the subjects named in this chapter appear. Every friend is one complete living plush with connected head/body, the canonical facial embroidery, colors and short limbs. No duplicate identities or reference-sheet triplets. Warm cooperative tone throughout, no distress or injury. Keep the same meadow geography, current evening light and precise prop ownership. Maintain all shot intervals exactly and a usable final hold. Full-width 21:9 image with no artificial black bars. No text of any kind, title cards, subtitles or end credits.\n'
        chapter.update(prompt=prompt,initial_prompt=prompt,planning_status='final_asset_grounded_direction',resolution='720p',audio='Native Foley, gentle instrumental celesta/pizzicato and wordless humming. No dialogue or lyrics.')
        directory=ROOT/'chapters'/chapter['id']
        directory.mkdir(parents=True,exist_ok=True)
        (directory/'prompt-v01.txt').write_text(prompt,encoding='utf-8')
    proposal['detailed_script']=proposal['detailed_script'].replace('Aspect: 16:9.','Aspect: 21:9.')
    (ROOT/'script.md').write_text(proposal['detailed_script'],encoding='utf-8')
    prepare.write_json(ROOT/'proposal.json',proposal)
    result=prepare.helper.save(ROOT,current,proposal,'Finalize approved-asset scene direction for exact 120s, native 720p 21:9')
    print(json.dumps(result))

if __name__=='__main__': main()
